using System.Collections.Generic;
using MassiveArmy.Industrial;
using UnityEngine;
namespace MassiveArmy.Planetary {
    // One projection for offline and server construction. All owners on a body
    // are included when replacing its existing journalled construction state.
    internal static class PlayerBuildProjection {
        static readonly PlayerModuleProfile[] Profiles=PlayerBuildingProfiles.Create(true);
        internal static void Commit(IndustrialAuthority authority,long actor,int body,PlayerBuildStorage storage,List<ItemStack> payment,bool refund){
            var logistics=new List<IndustrialModulePorts>();var obstacles=new List<IndustrialHaulObstacle>();var sources=new List<IndustrialConstructionSource>();var mounts=new List<IndustrialMount>();var profiles=Profiles;foreach(var site in storage.playerBuildSites)foreach(var module in site.modules){var modulePoint=site.anchor+Double3.Rotate(site.rotation,new Double3(module.position));if(module.constructionActivity>0)sources.Add(new IndustrialConstructionSource{module=module.id,activity=module.constructionActivity,pose=new FramePose{body=body,x=modulePoint.x,y=modulePoint.y,z=modulePoint.z}});var profile=profiles[(int)module.kind];if(module.kind==PlayerModuleKind.WorkshopRoom||module.kind==PlayerModuleKind.WarehouseRoom){var asset=ColonyPrototypeLibrary.StoredProfile("room-"+module.kind);var rotation=site.rotation*Quaternion.Euler(0,module.yaw,0);var ports=new IndustrialModulePorts{site=site.id,module=module.id,owner=site.owner>0?site.owner:actor,pose=new FramePose{body=body,x=modulePoint.x,y=modulePoint.y,z=modulePoint.z,yaw=(Quaternion.Inverse(Quaternion.FromToRotation(Vector3.up,PlanetPrecisionPolicy.Direction(modulePoint)))*rotation).eulerAngles.y}};foreach(var socket in asset.sockets){if(socket.kind!="ConveyorInput"&&socket.kind!="ConveyorOutput")continue;var at=modulePoint+Double3.Rotate(rotation,new Double3(socket.position));var pin=new FramePose{body=body,x=at.x,y=at.y,z=at.z};if(socket.kind=="ConveyorInput")ports.input=pin;else ports.output=pin;}logistics.Add(ports);}if(!profile.Foundation&&profile.bounds.size.y>1){var centre=modulePoint+Double3.Rotate(site.rotation*Quaternion.Euler(0,module.yaw,0),new Double3(new Vector3(profile.bounds.center.x,0,profile.bounds.center.z)));obstacles.Add(new IndustrialHaulObstacle{module=module.id,pose=new FramePose{body=body,x=centre.x,y=centre.y,z=centre.z,yaw=(Quaternion.Inverse(Quaternion.FromToRotation(Vector3.up,PlanetPrecisionPolicy.Direction(centre)))*site.rotation*Quaternion.Euler(0,module.yaw,0)).eulerAngles.y},halfWidth=profile.bounds.extents.x,halfDepth=profile.bounds.extents.z,height=profile.bounds.max.y,radius=new Vector2(profile.bounds.extents.x,profile.bounds.extents.z).magnitude});}for(int n=0;n<profile.outputs.Length;n++){var socket=profile.outputs[n];if(socket.kind!=BuildSocketKind.MachineMount&&!(socket.kind==BuildSocketKind.FloorCenter&&(profile.Foundation||module.kind==PlayerModuleKind.CeilingSquare)))continue;var point=site.anchor+Double3.Rotate(site.rotation,new Double3(module.position+Quaternion.Euler(0,module.yaw,0)*socket.point));var rotation=site.rotation*Quaternion.Euler(0,module.yaw+socket.yaw,0);float yaw=(Quaternion.Inverse(Quaternion.FromToRotation(Vector3.up,PlanetPrecisionPolicy.Direction(point)))*rotation).eulerAngles.y;mounts.Add(new IndustrialMount{site=site.id,module=module.id,socket=n,owner=site.owner>0?site.owner:actor,width=socket.width,depth=socket.depth,pose=new FramePose{body=body,x=point.x,y=point.y,z=point.z,yaw=yaw}});}}
            authority.CommitConstructionResources(actor,body,JsonUtility.ToJson(storage),payment,refund,mounts,sources,obstacles,logistics);
        }
    }
}
